t.script:
(function () {
    var apiHost = ''.replace(/\/$/, '');
    function initPostHog() {
        posthog.init('', {
            api_host: apiHost,

            bootstrap: ,

        });

        // registers the experiment exposure ($feature_flag_called)
        posthog.getFeatureFlag('');

    }
    function loadPostHog() {
        var script = document.createElement('script');
        script.async = true;
        // PostHog Cloud serves the SDK from the assets domain;
        // self-hosted instances serve it from the app host
        script.src = apiHost.replace('.i.posthog.com', '-assets.i.posthog.com') + '/static/array.js';
        script.onload = initPostHog;
        document.head.appendChild(script);
    }

    loadPostHog();


    document.addEventListener('optionalCookiesAccepted', loadPostHog, {once: true});

})();
